import sys
import math

# Since the original code uses atcoder's static_modint, we implement a simple modular integer class
class ModInt:
    def __init__(self, value, mod):
        self.mod = mod
        self.value = value % mod

    def __add__(self, other):
        return ModInt(self.value + other.value, self.mod)

    def __sub__(self, other):
        return ModInt(self.value - other.value, self.mod)

    def __mul__(self, other):
        return ModInt(self.value * other.value, self.mod)

    def __truediv__(self, other):
        return self * other.inv()

    def __repr__(self):
        return str(self.value)

    def val(self):
        return self.value

    def inv(self):
        # Extended Euclidean Algorithm for modular inverse
        a, m = self.value, self.mod
        g, x, y = extended_gcd(a, m)
        if g != 1:
            raise Exception('No inverse')
        else:
            return ModInt(x % m, self.mod)

def extended_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, y, x = extended_gcd(b, a % b)
        return (g, x, y - (a // b) * x)

def main():
    input = sys.stdin.read
    data = input().split()
    n, m, mod = map(int, data)

    # Precompute binomial coefficients
    C = [[ModInt(0, mod) for _ in range(n + 1)] for _ in range(n + 1)]
    C[0][0] = ModInt(1, mod)
    for i in range(1, n + 1):
        C[i][0] = ModInt(1, mod)
        for j in range(1, n + 1):
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j]

    # Compute g array
    g = [i * (i + 1) // 2 for i in range(n + 1)]

    # Compute f array
    f = [(ModInt(1, mod), ModInt(0, mod))] + [(ModInt(0, mod), ModInt(0, mod)) for _ in range(n)]
    for i in range(1, n + 1):
        fi_first = ModInt(0, mod)
        fi_second = ModInt(0, mod)
        for j in range(i):
            z = f[j][0] * f[i - 1 - j][0] * C[i - 1][j]
            fi_first += z * ModInt(i + 1, mod)
            fi_second += z * (ModInt(g[j], mod) + ModInt(g[i - 1 - j], mod))
            fi_second += (f[i - 1 - j][0] * f[j][1] + f[j][0] * f[i - 1 - j][1]) * C[i - 1][j] * ModInt(i + 1, mod)
        f[i] = (fi_first, fi_second)

    # Initialize DP array
    dp = [[(ModInt(0, mod), ModInt(0, mod)) for _ in range(m + 1)] for _ in range(n + 2)]
    dp[0][0] = (ModInt(1, mod), ModInt(0, mod))

    for l in range(n + 1):
        for r in range(l + 1, n + 2):
            di = r - l - 1
            for i in range(m - di + 1):
                z = dp[l][i][0] * f[di][0]
                dp[r][i + di] = (
                    dp[r][i + di][0] + z * C[i + di][di],
                    dp[r][i + di][1] + (dp[l][i][1] * f[di][0] + dp[l][i][0] * f[di][1]) * C[i + di][di]
                )

    print(dp[n + 1][m][1].val())

confidence = 0.9
print(f"<confidence>\n{confidence}\n</confidence>")
